              </div>
            </div>
          </div>
        )}

        {state.activeWorkspace === 'look-lighting' && (
          <LookTab state={state} store={store} />
        )}

        {state.activeWorkspace === 'scene-layout' && (
          <SceneTab state={state} store={store} />
