  wave: Wave;
  freqStart: number;
  freqEnd: number;
  cutoffHz: number;
  resonanceQ: number;
  volume: number;
  durationMs: number;
}

const INITIAL_STEMS: StudioAudioStem[] = [
  {
    id: 'stem:mill-motor',
    label: 'Texture Mill Motor Hum',
    stageUnlock: 0,
    wave: 'sawtooth',
    freqStart: 110,
    freqEnd: 115,
